// app/Events/OrderPaid.php
class OrderPaid implements ShouldDispatchAfterCommit
{
    use Dispatchable, SerializesModels;
    public function __construct(public readonly Order $order) {}
}

// app/Actions/PlaceOrder.php — the core action only knows the fact it announces
public function handle(User $user, array $data): Order
{
    $order = DB::transaction(function () use ($user, $data) {
        $order = Order::create([...]);
        // items, stock, ledger — the things that MUST exist together
        OrderPaid::dispatch($order);      // safe: fires after commit because of the interface
        return $order;
    });
    return $order;
}

// app/Listeners/SendReceipt.php — queued, retried, idempotent
class SendReceipt implements ShouldQueue
{
    public int $tries = 5;
    public array $backoff = [30, 120, 600];
    public function handle(OrderPaid $event): void
    {
        if ($event->order->receipt_sent_at) return;
        Mail::to($event->order->user)->send(new ReceiptMail($event->order));
        $event->order->update(['receipt_sent_at' => now()]);
    }
    public function failed(OrderPaid $event, \Throwable $e): void { Log::critical('receipt failed', ['order' => $event->order->id]); }
}
