public function test_nothing_happens_on_rollback(): void {
    Queue::fake();
    $order = Order::factory()->create();
    try {
        DB::transaction(function () use ($order) { OrderPaid::dispatch($order); throw new \RuntimeException('boom'); });
    } catch (\RuntimeException) {}
    Queue::assertNothingPushed();                         // queued listener never enqueued
    $this->assertDatabaseCount('audit_log', 0);           // sync listener never ran
}
public function test_everything_happens_on_commit(): void {
    Queue::fake();
    $order = Order::factory()->create();
    DB::transaction(fn () => OrderPaid::dispatch($order));
    Queue::assertPushed(CallQueuedListener::class, fn ($job) => $job->class === SendReceipt::class);
    $this->assertDatabaseCount('audit_log', 1);
}
// Remove ShouldDispatchAfterCommit from the event and watch the first test fail — that is the bug, reproduced.

// Does not fire observers (query builder, one UPDATE statement):
Order::where('status', 'pending')->update(['status' => 'cancelled']);

// Fires observers (one UPDATE per row; N saved() calls):
Order::where('status', 'pending')->chunkById(500, function ($orders) {
    foreach ($orders as $o) { $o->status = 'cancelled'; $o->save(); }
});

// Cost: N statements and N observer runs instead of 1 statement. For 100k rows that's the difference between 1 second
// and minutes. So: bulk update when the side effect can be done in bulk too (Cache::flush a tag, one audit row for the batch),
// per-model save only when each row genuinely needs its hook.
